・東京都では都税として都税事務所が扱うが、試験上は「都道府県が課す」と理解してよい
・基準となるのは「取得者の住所地」ではなく「不動産の所在地」の都道府県★
　→東京在住の人が北海道の土地を買えば、課税するのは北海道

【図解】不動産取得税と固定資産税の課税主体対比
　項目｜不動産取得税｜固定資産税
　課税主体｜都道府県★｜市町村★
　課税の時期｜取得したとき1回限り★｜毎年（保有している間）★
　徴収方法｜普通徴収★｜普通徴収★
