・取得した者には、条例の定めにより取得の事実を都道府県へ申告する義務が課されているが、申告がなくても都道府県は職権で調査し課税できる★
・したがって「申告しなければ課税されない」は誤り。申告義務と課税は別問題である

【図解】普通徴収と申告納付の違い
　方式｜税額を計算するのは｜代表例
