・国・地方公共団体は取得しても課税されない（人的非課税）。逆に、国や地方公共団体から不動産を取得した私人には通常どおり課税される★
・宅建業者が取引に関与しても、自ら所有権を取得していなければ納税義務は負わない。あくまで「取得したかどうか」が基準である★
・共有で取得した場合、各共有者は持分に応じた税額について連帯して納付する義務を負う★
・取得した不動産をすぐに転売しても、いったん取得した事実は消えないので納税義務は残る★

【図解】取得者の属性別の課税の有無
　取得者｜課税｜根拠
　個人｜される★｜原則どおり
