　譲渡費用★｜売却時の仲介手数料、印紙税、立退料、取壊し費用★｜修繕費、引越費用、住宅ローンの利息★

・建物の取得費は、所有期間中の減価償却費相当額を差し引いた後の額となる★
　→土地は減価しないので、購入代金がそのまま取得費になる
・「売るために直接かかった費用」が譲渡費用。日常の維持管理費は含まれない★
・抵当権抹消費用や引越費用は譲渡費用に含まれないとされる★

