　→申告しなければ特例は受けられない。税額がゼロになる場合でも申告が必要である点が実務上の落とし穴である★
・譲渡損失が出た場合も、損益通算や繰越控除の特例を使うには申告が必要である★

★ここだけ暗記
・課税譲渡所得＝収入金額−（取得費＋譲渡費用）−特別控除★
・分離課税である★
・取得費には購入時の諸費用と改良費、建物は減価償却後★
・譲渡費用は売るために直接かかった費用のみ★
