短期間で転売を繰り返す投機的な取引には重く、長く持っていた資産の売却には軽く——これが長期・短期を分ける趣旨です。
そして宅建試験で最も狙われるのが「5年をいつの時点で数えるか」。答えは「譲渡した年の1月1日」です。実際の売却日ではありません。
