━━━━━━━━━━━━━━━━━━━━━━
・一つの文書が複数の号の課税文書に該当する場合、所属の決定に関するルールに従って、いずれか一つの号の文書として扱う★
・たとえば土地の売買と建物の建築請負を一つの契約書にまとめた場合、原則として売買契約書（第1号文書）として扱われるが、請負金額が売買金額を上回るときは請負契約書（第2号文書）となる★

