　課税★｜原則どおり課税される｜建物の売買、仲介手数料★
　非課税★｜課税対象だが法律で非課税とされる｜土地の売買、住宅の家賃★
　不課税★｜そもそも課税の対象外｜贈与、給与、保険金★

