これが収益還元法です。不動産が将来生み出す収益から逆算して価格を求めます。
賃貸物件だけの手法だと思われがちですが、自分で住む家（自用の不動産）にも「賃貸に出したらいくらか」を想定して適用できます。ここが試験の急所です。
証券化された不動産の評価では、この手法が中心になります。

