・収益還元法は、対象不動産が将来生み出すであろうと期待される純収益の現在価値の総和を求めることにより、対象不動産の試算価格を求める手法である★
・求められた価格を「収益価格」という★
・賃貸用不動産または賃貸以外の事業の用に供する不動産の価格を求める場合に特に有効である★
・自用の不動産であっても、賃貸を想定することにより適用できる★

【図解】収益還元法の適用範囲
　対象｜適用｜
